'use strict';
// One short closure per completed decision. Physics/results remain in the mission model.
(function(){
 const rules=window.MissionVideoRules,base='assets/videos/',playedFinals=new Set();let active=null,finalPlayer=null;
 document.body.insertAdjacentHTML('beforeend',`<dialog id="missionClipDialog" class="mission-clip-dialog" aria-labelledby="missionClipTitle"><div class="mission-clip-head"><div><span class="eyebrow">UN MOMENTO CON FÉLICETTE</span><h2 id="missionClipTitle"></h2></div><button id="skipMissionClip" class="primary">Omitir y seguir →</button></div><video id="missionClipPlayer" controls playsinline muted preload="metadata" aria-label="Cierre animado de esta decisión"></video><p id="missionClipCaption"></p><div class="mission-clip-actions"><button id="playMissionClip">▶ Reproducir escena</button><span id="missionClipStatus" role="status"></span></div></dialog>`);
 const dialog=$('missionClipDialog'),player=$('missionClipPlayer');
 function stop(video){if(!video)return;video.pause();video.removeAttribute('src');video.load();}
 function finish(continueMission=true){const state=active;if(!state||state.done)return;state.done=true;active=null;stop(player);if(dialog.open)dialog.close();if(continueMission&&mission.step===state.step&&!$('publicMission').hidden)state.next();}
 function play(video,status,button){button.hidden=false;status.textContent='';const p=video.play();if(p?.then)p.then(()=>{button.hidden=true;}).catch(()=>{status.textContent='Tocá Reproducir para ver la escena, o continuá cuando quieras.';});}
 function closure(clip,next){if(!clip){next();return;}if(active)return;active={step:mission.step,next,done:false};$('missionClipTitle').textContent=clip.title;$('missionClipCaption').textContent=clip.caption;$('missionClipStatus').textContent='Podés omitir la animación y seguir con tu misión.';$('skipMissionClip').textContent='Omitir y seguir →';player.poster=base+clip.name+'_portada.jpg';player.src=base+clip.name+'.mp4';player.muted=true;dialog.showModal();$('playMissionClip').hidden=false;if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.hidden)play(player,$('missionClipStatus'),$('playMissionClip'));}
 $('skipMissionClip').onclick=()=>finish();$('playMissionClip').onclick=()=>play(player,$('missionClipStatus'),$('playMissionClip'));player.onended=()=>finish();player.onerror=()=>{if(!active)return;$('missionClipStatus').textContent='La escena no pudo cargarse. Podés seguir con la misión.';$('skipMissionClip').textContent='Continuar con mi misión →';$('playMissionClip').hidden=false;};dialog.oncancel=e=>{e.preventDefault();finish();};dialog.onclose=()=>finish();
 const next=$('gameNext').onclick;$('gameNext').onclick=()=>{if($('gameNext').disabled||active||!records.length||!RM.ready)return;closure(rules.micro(mission.step),next);};
 function finalSignature(){return JSON.stringify({goal:mission.goal,site:sites[mission.site],date:mission.date,capacity:mission.capacity,tracking:mission.tracking,height:mission.height,store:mission.store,radius:RM.radius,margin:RM.margin,panelHeight:RM.panelHeight});}
 function mountFinal(){if(mission.step!==6||!journeyStarted||!RM.ready||$('publicMission').hidden)return;const analysis=missionAnalysis(),info=RM.terrain.inspect(sites[mission.site],RM.radius),result=rules.ending(mission,analysis,info.slope,10),key=finalSignature(),section=document.createElement('section');section.className='mission-final-movie '+(result.kind==='review'?'needs-review':'');section.id='missionFinalMovie';section.dataset.ending=result.name;section.innerHTML=`<div class="mission-final-copy"><span class="eyebrow">EL CIERRE DE TU EXPERIENCIA</span><h2></h2><p class="mission-final-description"></p></div><video controls playsinline muted preload="metadata" aria-label="Escena final de tu plan de misión"></video><ul class="mission-ending-reasons"></ul><div class="mission-final-actions"><button class="replay-mission-ending">▶ Ver escena</button><button class="retry-mission-plan">↶ Volver a intentarlo</button><span class="mission-video-status" role="status"></span></div><p class="mission-video-note">Ilustración narrativa: no representa el lugar ni la fecha calculados. Los resultados, advertencias y exportación de tu plan están debajo.</p>`;section.querySelector('h2').textContent=result.title;section.querySelector('.mission-final-description').textContent=result.caption;for(const reason of result.reasons){const li=document.createElement('li');li.textContent=reason;section.querySelector('ul').append(li);}section.querySelector('ul').hidden=!result.reasons.length;
  $('gameContent').prepend(section);const video=section.querySelector('video'),button=section.querySelector('.replay-mission-ending'),status=section.querySelector('.mission-video-status');finalPlayer=video;video.poster=base+result.name+'_portada.jpg';video.src=base+result.name+'.mp4';video.muted=true;video.onerror=()=>{status.textContent='La escena no pudo cargarse. Tu plan y sus resultados siguen disponibles.';button.hidden=false;};video.onended=()=>{button.textContent='↻ Volver a ver';button.hidden=false;status.textContent='Podés revisar tus resultados y decidir el siguiente paso.';};button.onclick=()=>{video.currentTime=0;play(video,status,button);};section.querySelector('.retry-mission-plan').onclick=()=>{stop(video);missionFeedback=null;mission.step=5;renderMission();$('gameStageTitle')?.focus({preventScroll:true});window.scrollTo({top:0,behavior:'instant'});};
  if(!playedFinals.has(key)){playedFinals.add(key);if(!matchMedia('(prefers-reduced-motion: reduce)').matches&&!document.hidden)play(video,status,button);else status.textContent='Reproducí la escena cuando quieras o revisá tu plan debajo.';}
 }
 const render=renderMission;renderMission=function(){if(finalPlayer){stop(finalPlayer);finalPlayer=null;}if(active&&active.step!==mission.step)finish(false);render();mountFinal();};
 const restart=$('restartMission').onclick;$('restartMission').onclick=()=>{finish(false);playedFinals.clear();if(finalPlayer){stop(finalPlayer);finalPlayer=null;}restart();};
 window.addEventListener('hashchange',()=>{if(location.hash!=='#mission'){finish(false);finalPlayer?.pause();}});document.addEventListener('visibilitychange',()=>{if(document.hidden){player.pause();finalPlayer?.pause();if(active){$('playMissionClip').hidden=false;$('missionClipStatus').textContent='La escena está pausada. Podés reproducirla o seguir.';}}});
 if(!$('publicMission').hidden)renderMission();
})();
